"""Build an isolated ERP design prototype. Does not change Django files."""
from pathlib import Path
import runpy
import json

folder = Path(__file__).resolve().parent
base = runpy.run_path(str(folder / 'build_preview.py'))
shell = base['shell']
css = '''
.content{padding:22px 26px}.preview-note{padding:6px 16px;font-size:10px}.topbar{height:60px}.page-header{margin-bottom:17px}.page-header h1{font-size:25px}.page-header p{font-size:12px;margin-top:6px}.kicker{font-size:9px;margin-bottom:5px}.date-box{font-size:10px}.button{display:inline-flex;align-items:center;justify-content:center;gap:8px;padding:10px 13px}.stats{grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin-bottom:13px}.card{padding:17px;border-radius:10px}.stat-value{font-size:27px;margin-top:9px}.stat-change{margin-top:7px;font-size:10px}.stat-title{font-size:9px}.stat-link{text-decoration:none;color:var(--ink);display:block}.stat-link:hover{border-color:var(--ink)}.erp-strip{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));background:var(--cream);border:1px solid var(--line);border-radius:10px;margin-bottom:16px}.erp-strip a{display:flex;align-items:center;justify-content:space-between;padding:13px 17px;border-right:1px solid var(--line);text-decoration:none;color:var(--ink);font-size:11px;gap:8px}.erp-strip a:last-child{border:0}.erp-strip strong{font-size:17px}.erp-main{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(260px,1fr);gap:14px;margin-bottom:14px}.erp-bottom{display:grid;grid-template-columns:minmax(0,1.7fr) minmax(260px,1fr);gap:14px}.card-header{margin-bottom:12px}.card-header h3{font-size:10px}.card-header a{font-size:10px}.chart-total{display:flex;align-items:baseline;gap:10px;margin:4px 0 12px}.chart-total strong{font-size:24px}.chart-total span{font-size:10px;color:var(--muted)}.trend{height:116px;display:flex;gap:10px}.axis{display:flex;flex-direction:column;justify-content:space-between;font-size:9px;color:var(--muted);padding-bottom:18px}.bars{display:flex;align-items:flex-end;justify-content:space-around;gap:12px;flex:1;border-bottom:1px solid var(--line);padding:0 10px 18px;background:repeating-linear-gradient(to top,transparent 0,transparent 32px,var(--cream) 32px,var(--cream) 33px)}.bar-item{height:100%;flex:1;display:flex;align-items:center;justify-content:flex-end;flex-direction:column;position:relative}.bar{background:var(--ink);width:65%;max-width:34px;border-radius:3px 3px 0 0;min-height:2px}.bar-item span{position:absolute;bottom:-15px;color:var(--muted);font-size:9px}.alert-row{padding:10px 0;text-decoration:none;color:var(--ink)}.alert-row strong{font-size:11px;margin-bottom:3px}.alert-row small{font-size:10px}.pill{font-size:9px}.card table td{padding:10px 7px;font-size:11px}.card table th{padding:7px;font-size:9px}.metric-row{padding:10px 0;font-size:11px}.footer-note{margin-top:11px;font-size:10px}.quick-actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}.quick-actions a{font-size:10px;padding:8px 10px}.section-subtitle{font-size:11px}.module-heading{margin-bottom:20px}.module-heading h1{font-size:28px;margin-bottom:8px}.module-heading p{font-size:12px;color:var(--muted)}.module-label{margin-bottom:18px;display:inline-block}.table-wrapper{max-width:100%}.topbar .search-box{width:260px}.balance{font-size:21px;font-weight:700;margin-bottom:12px}.muted{color:var(--muted)}.sidebar{height:100vh;min-height:0}.logo{height:60px}.menu{padding-top:8px}.menu-item{height:36px;font-size:12px}.menu-title{padding-top:11px}.company-box{padding:13px 20px}.topbar .user-info strong{font-size:12px}.notification{display:none}.button.secondary:hover,.erp-strip a:hover{background:var(--cream)}.menu-item[aria-current=page]{background:var(--ink);color:var(--bg)}
@media(min-width:1200px) and (min-height:850px){.content{padding-top:28px}.card{padding:21px}.trend{height:160px}.alert-row{padding:13px 0}.card table td{padding:14px 7px}}
@media(max-width:1100px){.erp-main,.erp-bottom{grid-template-columns:minmax(0,1.4fr) minmax(230px,1fr)}.content{padding:18px}.stats{grid-template-columns:repeat(2,minmax(0,1fr))}.erp-strip{grid-template-columns:repeat(2,minmax(0,1fr))}.erp-strip a:nth-child(2){border-right:0}.topbar .search-box{width:190px}}
@media(max-width:800px){.erp-main,.erp-bottom{grid-template-columns:1fr}.page-header{align-items:flex-start;flex-direction:column}.actions{width:auto}.erp-strip a{padding:12px}.topbar .search-box{display:none}}@media(max-width:420px){.stats{gap:8px}.card{padding:13px}.stat-value{font-size:23px}.erp-strip{grid-template-columns:1fr}.erp-strip a{border-right:0;border-bottom:1px solid var(--line)}.content{padding:14px 10px}.date-box{padding:8px}.topbar{padding:0 12px}}
'''
css += '''
.line-plot{flex:1;min-width:0;display:flex;flex-direction:column}.line-plot svg{display:block;width:100%;flex:1;min-height:0;overflow:visible}.sales-line{fill:none;stroke:var(--ink);stroke-width:2.5;stroke-linecap:round;stroke-linejoin:round;vector-effect:non-scaling-stroke}.line-grid{stroke:var(--line);stroke-width:1;vector-effect:non-scaling-stroke}.line-labels{display:flex;justify-content:space-between;padding-top:6px;font-size:9px;color:var(--muted)}.line-labels span{width:28px;text-align:center}.admin-scope{display:inline-flex;align-items:center;gap:6px;font-size:10px;color:var(--muted)}
'''
shell = shell.replace('</head>', '<style>'+css+'</style></head>')
icon = base['icon']
def metric(title, value, note, module, glyph):
    return f'<a href="#{module}" class="card stat-link"><div class="stat-top"><span class="stat-title">{title}</span>{icon(glyph)}</div><div class="stat-value">{value}</div><div class="stat-change">{note} ↗</div></a>'
metrics = ''.join(metric(*r) for r in [
    ("Today's sales",'₹24,850','32 orders today','sales','sales'),
    ('Receivables','₹18,400','8 unpaid invoices','customers','users'),
    ('Payables','₹32,600','5 supplier bills','purchases','bag'),
    ("Today's expenses",'₹3,250','4 recorded expenses','expenses','card')])
strip = ''.join(f'<a href="#{module}"><span>{title}</span><strong>{value} <span style="font-size:11px">↗</span></strong></a>' for title,value,module in [('Products','248','products'),('Stock units','3,842','inventory'),('Employees','18','employees'),('Branches','4','branches')])
sales = [('Tue',14200),('Wed',18600),('Thu',16850),('Fri',22100),('Sat',27900),('Sun',22300),('Mon',24850)]
points = ' '.join(f'{14+i*92},{100-value/30000*100:.2f}' for i, (_,value) in enumerate(sales))
line_chart = f'''<div class="line-plot"><svg viewBox="0 0 580 100" preserveAspectRatio="none" aria-hidden="true"><path class="line-grid" d="M14 0H566 M14 50H566 M14 100H566"/><polyline class="sales-line" points="{points}"/></svg><div class="line-labels">{''.join(f'<span>{day}</span>' for day,_ in sales)}</div></div>'''
alerts = ''.join(f'<a class="alert-row" href="#{module}"><div><strong>{title}</strong><small>{sub}</small></div><span class="pill">{badge} →</span></a>' for title,sub,badge,module in [('Stock needs replenishment','20 low stock · 10 out of stock','30 items','inventory'),('Supplier bills due','Review payments due today','₹12,600','purchases'),('Customer invoices overdue','Follow up on 3 unpaid invoices','₹7,200','customers')])
overview = f'''
<div class="page-header"><div><div class="kicker">Administrator workspace · Company-wide overview</div><h1>Admin dashboard</h1><p>Monitor business performance, oversee your team, and manage every branch.</p></div><div class="actions"><span class="date-box">26 OCT 2026</span><a class="button" href="#reports">{icon('bars')} View reports</a></div></div>
<div class="stats">{metrics}</div><div class="erp-strip">{strip}</div>
<div class="erp-main"><article class="card"><div class="card-header"><h3>Sales performance</h3><a href="#sales">Sales details →</a></div><div class="chart-total"><strong>₹1,46,800</strong><span>20–26 October · Last 7 days</span></div><div class="trend" role="img" aria-label="Sample daily sales from October 20 to 26: 14200, 18600, 16850, 22100, 27900, 22300, 24850 rupees"><div class="axis"><span>₹30k</span><span>₹15k</span><span>₹0</span></div>{line_chart}</div></article>
<article class="card attention"><div class="card-header"><h3>Needs your attention</h3><span class="pill">3 priorities</span></div>{alerts}</article></div>
<div class="erp-bottom"><article class="card"><div class="card-header"><h3>Latest transactions</h3><a href="#sales">View sales →</a></div><div class="table-wrapper"><table><thead><tr><th>Reference</th><th>Type</th><th>Party</th><th class="numeric">Amount</th><th>Status</th></tr></thead><tbody><tr><td>INV-1048</td><td>Sale</td><td>Walk-in customer</td><td class="numeric">₹2,450</td><td><span class="pill">Paid</span></td></tr><tr><td>PO-0286</td><td>Purchase</td><td>Freshline Supplies</td><td class="numeric">₹12,600</td><td><span class="pill">Due today</span></td></tr><tr><td>EXP-0094</td><td>Expense</td><td>Store utilities</td><td class="numeric">₹850</td><td><span class="pill">Paid</span></td></tr></tbody></table></div></article>
<article class="card"><div class="card-header"><h3>Admin controls</h3><a href="#reports">Reports →</a></div><div class="metric-row"><span>Inventory purchase value</span><strong>₹4,86,250</strong></div><div class="metric-row"><span>Pending purchase orders</span><a href="#purchases">6 orders →</a></div><div class="metric-row"><span>Returns awaiting review</span><a href="#returns">2 returns →</a></div><div class="quick-actions"><a class="button secondary" href="#branches">Branches</a><a class="button secondary" href="#employees">Employees</a><a class="button secondary" href="#company-settings">Settings</a></div></article></div>
<p class="footer-note">All values are sample data. Select a sidebar module for its detailed page. Sales, finance, and other planned modules require backend implementation.</p>'''

# Each sidebar entry opens its own module screen within this offline prototype.
modules = {
'sales': ['Sales','Review invoices, payments, and daily sales.', ['Invoice','Customer','Amount','Status'], [['INV-1048','Walk-in customer','₹2,450','Paid'],['INV-1047','Anita Stores','₹4,800','Unpaid'],['INV-1046','Walk-in customer','₹1,200','Paid']], [('Sales today','₹24,850'),('Orders today','32'),('Unpaid invoices','8')]],
'pos': ['POS','A proposed checkout workspace for counter sales.', ['Product','Price','Available','Category'], [['Basmati Rice · 5 kg','₹620','4 units','Groceries'],['Toor Dal · 1 kg','₹160','86 units','Groceries'],['Whole Wheat Flour · 5 kg','₹280','6 units','Groceries']], [('Cart items','0'),('Subtotal','₹0'),('Total','₹0')]],
'products': ['Products','Manage your product catalog, pricing, and categories.', ['Product','SKU','Selling price','Status'], [['Basmati Rice · 5 kg','SKU-RC-005','₹620','Active'],['Sunflower Oil · 1 L','SKU-OL-001','₹145','Active'],['Toor Dal · 1 kg','SKU-DL-001','₹160','Active']], [('Active products','248'),('Categories','12'),('Inactive products','8')]],
'inventory': ['Inventory','Company-wide stock levels and replenishment priorities.', ['Product','Available','Minimum','Status'], [['Basmati Rice · 5 kg','4','10','Low stock'],['Sunflower Oil · 1 L','0','15','Out of stock'],['Whole Wheat Flour · 5 kg','6','10','Low stock'],['Toor Dal · 1 kg','86','10','Healthy']], [('Stock units','3,842'),('Low stock','20'),('Out of stock','10')]],
'customers': ['Customers','Customer balances and outstanding invoices.', ['Customer','Outstanding','Overdue','Status'], [['Anita Stores','₹4,800','₹4,800','Follow up'],['City Mart','₹6,400','₹2,400','Follow up'],['Other customers','₹7,200','₹0','Within terms']], [('Receivables','₹18,400'),('Overdue balance','₹7,200'),('Unpaid invoices','8')]],
'purchases': ['Purchases','Track supplier orders, deliveries, and payments.', ['Order','Supplier','Amount','Status'], [['PO-0286','Freshline Supplies','₹12,600','Due today'],['PO-0285','Harvest Wholesale','₹8,400','Ordered'],['PO-0284','Daily Essentials','₹11,600','Awaiting delivery']], [('Pending orders','6'),('Payables','₹32,600'),('Due today','₹12,600')]],
'returns': ['Returns','Review customer returns and refund requests.', ['Reference','Original invoice','Amount','Status'], [['RET-0041','INV-1031','₹620','Awaiting review'],['RET-0040','INV-1028','₹280','Awaiting review']], [('Pending review','2'),('Requested refunds','₹900'),('Resolved today','0')]],
'employees': ['Employees','Your team, assigned roles, and online status.', ['Employee','ID','Role','Status'], [['Asha Kumar','ID001','Manager','Online'],['Ravi Shah','ID002','Cashier','Online'],['Neha Patel','ID003','Inventory Staff','Offline']], [('Team members','18'),('Online','6'),('Offline','12')]],
'branches': ['Branches','Stores, outlets, and warehouses in your company.', ['Branch','Code','Type','Status'], [['Main Store','BR-001','Retail Store','Active'],['City Outlet','BR-002','Outlet','Active'],['Central Warehouse','BR-003','Warehouse','Active'],['North Store','BR-004','Retail Store','Active']], [('Active branches','4'),('Retail stores','2'),('Warehouses','1')]],
'expenses': ['Expenses','Review business expenses and payment records.', ['Reference','Category','Amount','Status'], [['EXP-0094','Store utilities','₹850','Paid'],['EXP-0093','Transport','₹1,200','Paid'],['EXP-0092','Packaging','₹700','Paid'],['EXP-0091','Maintenance','₹500','Paid']], [("Today's expenses",'₹3,250'),('Entries today','4'),('Unpaid today','₹0')]],
'reports': ['Reports','A central place for business and operational reports.', ['Report','Coverage','Period','Preview status'], [['Sales summary','Revenue and orders','Last 7 days','Sample available'],['Inventory valuation','Company-wide inventory','Current snapshot','Sample available'],['Receivables aging','Customer balances','Current snapshot','Sample available']], [('Weekly sales','₹1,46,800'),('Stock value','₹4,86,250'),('Receivables','₹18,400')]],
'company-settings': ['Company Settings','Company identity and operating preferences.', ['Setting','Sample value'], [['Company','Your company'],['Country','India'],['Currency','INR'],['Account role','Administrator']], [('Company','1'),('Branches','4'),('Currency','INR')]],
'business-settings': ['Business Settings','Proposed controls for everyday business operations.', ['Setting','Sample value'], [['Default currency','INR'],['Stock alert rule','Per-product minimum'],['Invoice prefix','INV'],['Purchase order prefix','PO']], [('Currency','INR'),('Stock alerts','Enabled'),('Invoice prefix','INV')]],
}
script = '''
const modules = MODULES;
const screen = document.getElementById('screen');
const overview = screen.innerHTML;
function toggleSidebar(){const s=document.getElementById('sidebar');s.classList.toggle('collapsed');document.querySelector('.toggle-btn').setAttribute('aria-expanded',String(!s.classList.contains('collapsed')))}
const slug = text => text.trim().toLowerCase().replaceAll(' ','-');
document.querySelectorAll('.menu-item').forEach(a=>{const name=a.textContent.trim();a.href='#'+slug(name);a.title=name;a.setAttribute('aria-label',name)});
function render(){
 const key=location.hash.slice(1)||'dashboard';
 const info=modules[key];
 if(!info){screen.innerHTML=overview;document.title='Admin dashboard | RetailFlow preview'}
 else {
  const [name,description,columns,rows,stats]=info;
  const cards=stats.map(([label,value])=>'<article class="card"><div class="stat-title">'+label+'</div><div class="stat-value">'+value+'</div></article>').join('');
  const heads=columns.map(c=>'<th>'+c+'</th>').join('');
  const body=rows.map(row=>'<tr>'+row.map(cell=>'<td>'+cell+'</td>').join('')+'</tr>').join('');
  screen.innerHTML='<div class="module-heading"><a class="card-header" href="#dashboard">← Business overview</a><div class="kicker">Administrator workspace</div><h1>'+name+'</h1><p>'+description+'</p></div><span class="pill module-label">Interactive layout proposal · Sample data</span><div class="stats">'+cards+'</div><article class="card"><div class="card-header"><h3>'+name+' overview</h3><span class="muted" style="font-size:11px">Sample records</span></div><div class="table-wrapper"><table><thead><tr>'+heads+'</tr></thead><tbody>'+body+'</tbody></table></div></article><p class="footer-note">This is a navigation and layout mockup. Data entry, payments, checkout, and backend connections are not implemented.</p>';
  document.title=name+' | RetailFlow preview';
 }
 document.querySelectorAll('.menu-item').forEach(a=>{const active=a.hash==='#'+(info?key:'dashboard');a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});
 window.scrollTo(0,0);
 if(location.hash){const heading=screen.querySelector('h1');heading.tabIndex=-1;heading.focus({preventScroll:true})}
}
window.addEventListener('hashchange',render);render();
document.querySelector('.search-box input').setAttribute('aria-label','Search sidebar modules');
document.querySelector('.search-box input').addEventListener('input',e=>document.querySelectorAll('.menu-item').forEach(a=>a.hidden=!a.textContent.toLowerCase().includes(e.target.value.toLowerCase())));
'''.replace('MODULES', json.dumps(modules, ensure_ascii=False))
html = shell + '<div class="preview-note">DESIGN PROPOSAL 02 · ERP overview · All figures are illustrative</div><section class="content" id="screen">'+overview+'</section></main></div><script>'+script+'</script></body></html>'
(folder / 'dashboard-proposal.html').write_text(html, encoding='utf-8')
(folder / 'preview-script.js').write_text(script, encoding='utf-8')
print('Built ERP overview and 13 navigable module previews.')
